// ─── Types ────────────────────────────────────────────────────────────────────

type ImportSource = 'excel' | 'website' | 'social_media' | 'api';

interface WebFormField {
  key_name: string;
  alias_name: string;
  key_type: string;
  is_required?: boolean;
  order_id: number;
  item_id: number;
}

interface FieldMapping {
  sourceField: string;
  targetField: string;
  targetAlias: string;
  sampleValue?: string;
  isRequired?: boolean;
}

interface TrackingFields {
  sourceName: string;
  sourceCampaignName: string;
  sourceCampaignId: string;
  sourceAdName: string;
  sourceAdId: string;
}

interface WebsiteConfig { url: string; formSelector: string; apiKey: string; }
interface SocialConfig {
  platform: 'facebook' | 'instagram' | 'linkedin' | 'twitter' | '';
  accessToken: string; adAccountId: string; formId: string;
}
interface ApiConfig {
  endpointUrl: string; method: 'GET' | 'POST';
  authType: 'none' | 'bearer' | 'api_key' | 'basic';
  authValue: string; requestBody: string; responseMapping: string;
}

// ─── Utilities ────────────────────────────────────────────────────────────────

/** Read webForm fields from localStorage under "leadWebFormData" key */
const getWebFormFields = (): WebFormField[] => {
  try {
    const raw = localStorage.getItem('leadWebFormData');
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    const items =
      parsed?.webForm?.leads_form_items ??
      parsed?.leads_form_items ??
      {};
    return Object.values(items) as WebFormField[];
  } catch {
    return [];
  }
};


/** Flatten nested object to dot-notation keys, max depth 3 */
const flattenObject = (
  obj: Record<string, any>,
  prefix = '',
  depth = 0,
): Record<string, string> => {
  if (depth > 3) return {};
  const result: Record<string, string> = {};
  for (const [k, v] of Object.entries(obj ?? {})) {
    const key = prefix ? `${prefix}.${k}` : k;
    if (v !== null && typeof v === 'object' && !Array.isArray(v)) {
      Object.assign(result, flattenObject(v, key, depth + 1));
    } else {
      result[key] = Array.isArray(v) ? JSON.stringify(v) : String(v ?? '');
    }
  }
  return result;
};

/** Fuzzy match a source field name to a webForm field */
const autoMatch = (sourceField: string, fields: WebFormField[]): WebFormField | null => {
  const n = (s: string) => s.toLowerCase().replace(/[_\s\-\.]/g, '');
  const src = n(sourceField);
  return (
    fields.find(f => n(f.key_name) === src) ||
    fields.find(f => n(f.alias_name) === src) ||
    fields.find(f => src.includes(n(f.alias_name)) || n(f.alias_name).includes(src)) ||
    null
  );
};

